"use client"

import * as React from "react"
import {
  COLOR_THEME_ATTRIBUTE,
  COLOR_THEME_STORAGE_KEY,
  CUSTOM_COLOR_THEME,
  DEFAULT_COLOR_THEME,
  DEFAULT_CUSTOM_THEME,
  DEFAULT_RADIUS,
  clampCustomTheme,
  colorThemes,
  isColorThemeId,
  isRadius,
  radiusOptions,
  type ColorTheme,
  type ColorThemeId,
  type CustomTheme,
  type Radius,
} from "@/lib/themes"

/* ------------------------------------------------------------------ */
/*  Context                                                            */
/* ------------------------------------------------------------------ */

export interface ColorThemeContextValue {
  /** The id of the active color theme. */
  colorTheme: ColorThemeId
  /** The full registry entry for the active color theme. */
  theme: ColorTheme
  /** Every registered color theme, in display order. */
  themes: readonly ColorTheme[]
  /** Activate a color theme. Persists and syncs across tabs. */
  setColorTheme: (id: ColorThemeId) => void
  /** Back to the default color theme, default radius and default custom values. */
  resetColorTheme: () => void

  /** Hue and chroma used by the "custom" theme. */
  customTheme: CustomTheme
  /** Update the custom hue / chroma. Also activates the "custom" theme. */
  setCustomTheme: (value: Partial<CustomTheme>) => void

  /** Border radius in rem, applied as `--radius`. */
  radius: Radius
  setRadius: (value: Radius) => void
}

const ColorThemeContext = React.createContext<ColorThemeContextValue | null>(null)

/* ------------------------------------------------------------------ */
/*  Tiny external store backed by localStorage                        */
/* ------------------------------------------------------------------ */

const CHANGE_EVENT = "color-theme-change"
const TRANSITION_ATTRIBUTE = "data-theme-transition"
const TRANSITION_MS = 350

function subscribe(onChange: () => void) {
  window.addEventListener("storage", onChange)
  window.addEventListener(CHANGE_EVENT, onChange)
  return () => {
    window.removeEventListener("storage", onChange)
    window.removeEventListener(CHANGE_EVENT, onChange)
  }
}

function readStored(key: string): string | null {
  try {
    return window.localStorage.getItem(key)
  } catch {
    return null
  }
}

function writeStored(key: string, value: string) {
  try {
    window.localStorage.setItem(key, value)
  } catch {
    /* storage can be unavailable (private mode, blocked); the DOM still updates */
  }
}

function parseCustom(raw: string | null): CustomTheme {
  if (!raw) return DEFAULT_CUSTOM_THEME
  try {
    return clampCustomTheme(JSON.parse(raw))
  } catch {
    return DEFAULT_CUSTOM_THEME
  }
}

function parseRadius(raw: string | null): Radius {
  const n = raw === null ? NaN : Number(raw)
  return isRadius(n) ? n : DEFAULT_RADIUS
}

function applyCustom(value: CustomTheme) {
  const style = document.documentElement.style
  style.setProperty("--custom-hue", String(value.hue))
  style.setProperty("--custom-chroma", String(value.chroma))
}

function applyRadius(value: Radius) {
  document.documentElement.style.setProperty("--radius", `${value}rem`)
}

let transitionTimer: ReturnType<typeof setTimeout> | undefined

/** Cross-fade colors for one change, unless the visitor prefers reduced motion. */
function withTransition(run: () => void) {
  const root = document.documentElement
  const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  if (reduce) return run()
  root.setAttribute(TRANSITION_ATTRIBUTE, "")
  run()
  clearTimeout(transitionTimer)
  transitionTimer = setTimeout(() => root.removeAttribute(TRANSITION_ATTRIBUTE), TRANSITION_MS)
}

/**
 * Script that runs before React hydrates so the first paint already has the
 * right `data-theme`, custom hue / chroma and radius. Same technique
 * next-themes uses for light / dark.
 */
function inlineScript(storageKey: string, attribute: string, fallback: string, ids: readonly string[], radii: readonly number[]) {
  return `(function(){try{var k=${JSON.stringify(storageKey)},a=${JSON.stringify(attribute)},d=${JSON.stringify(fallback)},ok=${JSON.stringify(ids)},rs=${JSON.stringify(radii)},h=document.documentElement,s=h.style;var t=localStorage.getItem(k);if(!t||ok.indexOf(t)===-1)t=d;h.setAttribute(a,t);try{var c=JSON.parse(localStorage.getItem(k+"-custom"));if(c&&isFinite(c.hue)&&isFinite(c.chroma)){s.setProperty("--custom-hue",String(c.hue));s.setProperty("--custom-chroma",String(c.chroma))}}catch(e){}var r=parseFloat(localStorage.getItem(k+"-radius"));if(rs.indexOf(r)!==-1)s.setProperty("--radius",r+"rem")}catch(e){}})()`
}

/* ------------------------------------------------------------------ */
/*  Provider                                                           */
/* ------------------------------------------------------------------ */

export interface ColorThemeProviderProps {
  children: React.ReactNode
  /** Theme used when nothing is stored yet. Defaults to `"default"`. */
  defaultTheme?: ColorThemeId
  /** localStorage key. Defaults to `"color-theme"`. */
  storageKey?: string
  /** CSP nonce forwarded to the inline script. */
  nonce?: string
}

export function ColorThemeProvider({
  children,
  defaultTheme = DEFAULT_COLOR_THEME,
  storageKey = COLOR_THEME_STORAGE_KEY,
  nonce,
}: ColorThemeProviderProps) {
  const customKey = `${storageKey}-custom`
  const radiusKey = `${storageKey}-radius`

  // Raw strings are stable snapshots, so useSyncExternalStore never loops.
  const storedTheme = React.useSyncExternalStore(subscribe, () => readStored(storageKey), () => null)
  const storedCustom = React.useSyncExternalStore(subscribe, () => readStored(customKey), () => null)
  const storedRadius = React.useSyncExternalStore(subscribe, () => readStored(radiusKey), () => null)

  const colorTheme: ColorThemeId = isColorThemeId(storedTheme) ? storedTheme : defaultTheme
  const customTheme = React.useMemo(() => parseCustom(storedCustom), [storedCustom])
  const radius = React.useMemo(() => parseRadius(storedRadius), [storedRadius])

  const setColorTheme = React.useCallback(
    (id: ColorThemeId) => {
      if (!isColorThemeId(id)) return
      withTransition(() => {
        writeStored(storageKey, id)
        document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, id)
      })
      window.dispatchEvent(new Event(CHANGE_EVENT))
    },
    [storageKey]
  )

  const setCustomTheme = React.useCallback(
    (value: Partial<CustomTheme>) => {
      const next = clampCustomTheme({ ...parseCustom(readStored(customKey)), ...value })
      writeStored(customKey, JSON.stringify(next))
      applyCustom(next)
      if (readStored(storageKey) !== CUSTOM_COLOR_THEME) {
        writeStored(storageKey, CUSTOM_COLOR_THEME)
        document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, CUSTOM_COLOR_THEME)
      }
      window.dispatchEvent(new Event(CHANGE_EVENT))
    },
    [customKey, storageKey]
  )

  const setRadius = React.useCallback(
    (value: Radius) => {
      if (!isRadius(value)) return
      writeStored(radiusKey, String(value))
      applyRadius(value)
      window.dispatchEvent(new Event(CHANGE_EVENT))
    },
    [radiusKey]
  )

  const resetColorTheme = React.useCallback(() => {
    withTransition(() => {
      writeStored(storageKey, defaultTheme)
      writeStored(customKey, JSON.stringify(DEFAULT_CUSTOM_THEME))
      writeStored(radiusKey, String(DEFAULT_RADIUS))
      document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, defaultTheme)
      applyCustom(DEFAULT_CUSTOM_THEME)
      applyRadius(DEFAULT_RADIUS)
    })
    window.dispatchEvent(new Event(CHANGE_EVENT))
  }, [storageKey, customKey, radiusKey, defaultTheme])

  // Keep <html> aligned with the store (covers cross-tab updates).
  React.useEffect(() => {
    document.documentElement.setAttribute(COLOR_THEME_ATTRIBUTE, colorTheme)
  }, [colorTheme])
  React.useEffect(() => applyCustom(customTheme), [customTheme])
  React.useEffect(() => applyRadius(radius), [radius])

  const value = React.useMemo<ColorThemeContextValue>(
    () => ({
      colorTheme,
      theme: colorThemes.find((t) => t.id === colorTheme) ?? colorThemes[0],
      themes: colorThemes,
      setColorTheme,
      resetColorTheme,
      customTheme,
      setCustomTheme,
      radius,
      setRadius,
    }),
    [colorTheme, setColorTheme, resetColorTheme, customTheme, setCustomTheme, radius, setRadius]
  )

  const script = React.useMemo(
    () =>
      inlineScript(
        storageKey,
        COLOR_THEME_ATTRIBUTE,
        defaultTheme,
        colorThemes.map((t) => t.id),
        radiusOptions.map((r) => r.value)
      ),
    [storageKey, defaultTheme]
  )

  return (
    <ColorThemeContext.Provider value={value}>
      <script nonce={nonce} suppressHydrationWarning dangerouslySetInnerHTML={{ __html: script }} />
      {children}
    </ColorThemeContext.Provider>
  )
}

/* ------------------------------------------------------------------ */
/*  Hook                                                               */
/* ------------------------------------------------------------------ */

export function useColorTheme(): ColorThemeContextValue {
  const ctx = React.useContext(ColorThemeContext)
  if (!ctx) {
    throw new Error("useColorTheme must be used within <ColorThemeProvider>")
  }
  return ctx
}

"use client"

import * as React from "react"
import { ThemeProvider as NextThemesProvider, type ThemeProviderProps as NextThemesProviderProps } from "next-themes"
import { ColorThemeProvider, type ColorThemeProviderProps } from "./color-theme-provider"

export interface ThemeProviderProps extends Omit<NextThemesProviderProps, "children"> {
  children: React.ReactNode
  /** Props forwarded to the color theme layer. */
  color?: Omit<ColorThemeProviderProps, "children">
}

/**
 * Composes next-themes (light / dark / system via the `class` attribute)
 * with the color theme layer (`data-theme` attribute).
 *
 * Mode and color are independent: switching to dark never changes the
 * chosen color, and picking a color never changes the mode.
 */
export function ThemeProvider({ children, color, ...props }: ThemeProviderProps) {
  return (
    <NextThemesProvider
      attribute="class"
      defaultTheme="system"
      enableSystem
      disableTransitionOnChange
      {...props}
    >
      <ColorThemeProvider {...color}>{children}</ColorThemeProvider>
    </NextThemesProvider>
  )
}

export { ColorThemeProvider, useColorTheme } from "./color-theme-provider"

"use client"

import * as React from "react"
import * as PopoverPrimitive from "@radix-ui/react-popover"
import { PaletteIcon, RotateCcwIcon } from "lucide-react"
import { useColorTheme } from "./color-theme-provider"
import { ModeSegmentedControl } from "./mode-toggle"
import { ThemeCustomizer } from "./theme-customizer"
import { ThemeSwatch } from "./theme-swatch"
import { Button, buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

/**
 * Grid of every registered color theme. Reusable on its own
 * (the hero section uses it too).
 */
export function ColorThemeGrid({
  size = "md",
  className,
}: {
  size?: "sm" | "md" | "lg"
  className?: string
}) {
  const { themes, colorTheme, setColorTheme } = useColorTheme()

  return (
    <div role="radiogroup" aria-label="Color theme" className={cn("flex flex-wrap gap-2", className)}>
      {themes.map((t) => (
        <ThemeSwatch
          key={t.id}
          themeId={t.id}
          label={t.label}
          size={size}
          selected={t.id === colorTheme}
          onSelect={setColorTheme}
        />
      ))}
    </div>
  )
}

/**
 * The theme switcher: a popover with an appearance control (light / dark /
 * system) and the color theme grid. Drop it anywhere inside <ThemeProvider>.
 *
 * The popover is built on the Radix primitive directly so this component
 * works regardless of which shadcn/ui style (Radix or Base UI) the host app
 * uses.
 */
export function ThemeSwitcher({ className }: { className?: string }) {
  const { theme, colorTheme, resetColorTheme } = useColorTheme()

  return (
    <PopoverPrimitive.Root>
      {/* Styled with buttonVariants instead of asChild so the shadcn CLI can
          install this file unchanged into both Radix and Base UI projects. */}
      <PopoverPrimitive.Trigger
        aria-label="Open theme settings"
        className={cn(buttonVariants({ variant: "outline" }), "gap-2", className)}
      >
        <span aria-hidden className="size-3.5 rounded-full bg-primary ring-1 ring-foreground/10 ring-inset" />
        <span className="hidden sm:inline">{theme.label}</span>
        <PaletteIcon className="size-4 text-muted-foreground" />
      </PopoverPrimitive.Trigger>
      <PopoverPrimitive.Portal>
        <PopoverPrimitive.Content
          align="end"
          sideOffset={6}
          className={cn(
            "z-50 w-80 max-h-[calc(100dvh-5rem)] overflow-y-auto rounded-md border bg-popover p-0 text-popover-foreground shadow-md outline-hidden",
            "origin-(--radix-popover-content-transform-origin)",
            "data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95"
          )}
        >
          <section className="space-y-2 p-4">
            <h3 className="text-sm font-semibold">Appearance</h3>
            <ModeSegmentedControl />
          </section>
          <div role="separator" className="h-px w-full bg-border" />
          <section className="space-y-3 p-4">
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-semibold">Color</h3>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 gap-1 px-2 text-xs text-muted-foreground"
                onClick={resetColorTheme}
                disabled={colorTheme === "default"}
              >
                <RotateCcwIcon className="size-3" />
                Reset
              </Button>
            </div>
            <ColorThemeGrid size="md" className="grid grid-cols-7 place-items-center gap-y-3" />
            <p className="text-xs text-muted-foreground">
              <span className="font-medium text-foreground">{theme.label}</span> · {theme.description}
            </p>
          </section>
          <div role="separator" className="h-px w-full bg-border" />
          <section className="space-y-2 p-4">
            <h3 className="text-sm font-semibold">Customize</h3>
            <ThemeCustomizer />
          </section>
        </PopoverPrimitive.Content>
      </PopoverPrimitive.Portal>
    </PopoverPrimitive.Root>
  )
}

"use client"

import * as React from "react"
import * as SliderPrimitive from "@radix-ui/react-slider"
import { CheckIcon, CopyIcon } from "lucide-react"
import { useColorTheme } from "./color-theme-provider"
import { Button } from "@/components/ui/button"
import { CUSTOM_CHROMA_RANGE, CUSTOM_HUE_RANGE, radiusOptions, type ColorThemeId, type CustomTheme } from "@/lib/themes"
import { cn } from "@/lib/utils"

/* ------------------------------------------------------------------ */
/*  Copy CSS                                                           */
/* ------------------------------------------------------------------ */

const KNOBS = ["--theme-hue", "--theme-chroma", "--theme-l", "--theme-l-dark", "--theme-on-primary"] as const

/**
 * Builds the CSS a visitor needs to reproduce the current look in their own
 * app. Knob values are read from a probe element so this never drifts from
 * globals.css.
 */
export function getThemeCss(id: ColorThemeId, custom: CustomTheme, radius: number): string {
  const lines: string[] = [`/* next-themes-colors: ${id} theme */`]

  if (id === "custom") {
    lines.push(`[data-theme="custom"] { --theme-hue: ${custom.hue}; --theme-chroma: ${custom.chroma}; }`)
  } else if (id !== "default" && typeof document !== "undefined") {
    const probe = document.createElement("span")
    probe.setAttribute("data-theme", id)
    probe.style.display = "none"
    document.body.appendChild(probe)
    const styles = getComputedStyle(probe)
    const decls = KNOBS.map((k) => [k, styles.getPropertyValue(k).trim()] as const)
      .filter(([, v]) => v)
      .map(([k, v]) => `${k}: ${v};`)
    probe.remove()
    lines.push(`[data-theme="${id}"] { ${decls.join(" ")} }`)
  }

  lines.push(`:root { --radius: ${radius}rem; }`)
  return lines.join("\n")
}

function CopyCssButton({ className }: { className?: string }) {
  const { colorTheme, customTheme, radius } = useColorTheme()
  const [copied, setCopied] = React.useState(false)

  const copy = async () => {
    const css = getThemeCss(colorTheme, customTheme, radius)
    try {
      await navigator.clipboard.writeText(css)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      /* clipboard unavailable */
    }
  }

  return (
    <Button variant="outline" size="sm" onClick={copy} className={cn("gap-1.5", className)}>
      {copied ? <CheckIcon className="text-primary" /> : <CopyIcon />}
      {copied ? "Copied" : "Copy CSS"}
    </Button>
  )
}

/* ------------------------------------------------------------------ */
/*  Sliders                                                            */
/* ------------------------------------------------------------------ */

const hueTrack = `linear-gradient(to right, ${Array.from({ length: 13 }, (_, i) => `oklch(0.7 0.18 ${i * 30})`).join(", ")})`

function Slider({
  id,
  value,
  min,
  max,
  step,
  onValueChange,
  trackStyle,
  label,
}: {
  id: string
  value: number
  min: number
  max: number
  step: number
  onValueChange: (value: number) => void
  trackStyle?: React.CSSProperties
  label: string
}) {
  return (
    <SliderPrimitive.Root
      id={id}
      value={[value]}
      min={min}
      max={max}
      step={step}
      onValueChange={([v]) => onValueChange(v)}
      className="relative flex h-5 w-full touch-none items-center select-none"
    >
      <SliderPrimitive.Track className="relative h-2 w-full grow overflow-hidden rounded-full bg-muted" style={trackStyle}>
        {!trackStyle && <SliderPrimitive.Range className="absolute h-full bg-primary" />}
      </SliderPrimitive.Track>
      <SliderPrimitive.Thumb aria-label={label} className="block size-4 rounded-full border-2 border-background bg-primary shadow-sm ring-ring/50 transition-[box-shadow] hover:ring-4 focus-visible:ring-4 focus-visible:outline-hidden" />
    </SliderPrimitive.Root>
  )
}

/* ------------------------------------------------------------------ */
/*  Customizer                                                         */
/* ------------------------------------------------------------------ */

/**
 * Hue and chroma sliders for the "custom" theme, a radius picker and a
 * copy-CSS button. Used inside the ThemeSwitcher popover; works anywhere
 * inside <ThemeProvider>.
 */
export function ThemeCustomizer({ className }: { className?: string }) {
  const { colorTheme, customTheme, setCustomTheme, radius, setRadius } = useColorTheme()
  const hueId = React.useId()
  const chromaId = React.useId()
  const isCustom = colorTheme === "custom"

  return (
    <div className={cn("space-y-4", className)}>
      <div className="space-y-3">
        <div className="flex items-center justify-between">
          <label htmlFor={hueId} className="text-xs font-medium">
            Hue
          </label>
          <span className="font-mono text-xs text-muted-foreground tabular-nums">{Math.round(customTheme.hue)}°</span>
        </div>
        <Slider
          id={hueId}
          label="Hue"
          value={customTheme.hue}
          min={CUSTOM_HUE_RANGE.min}
          max={CUSTOM_HUE_RANGE.max}
          step={CUSTOM_HUE_RANGE.step}
          onValueChange={(hue) => setCustomTheme({ hue })}
          trackStyle={{ background: hueTrack }}
        />
        <div className="flex items-center justify-between">
          <label htmlFor={chromaId} className="text-xs font-medium">
            Chroma
          </label>
          <span className="font-mono text-xs text-muted-foreground tabular-nums">{customTheme.chroma.toFixed(3)}</span>
        </div>
        <Slider
          id={chromaId}
          label="Chroma"
          value={customTheme.chroma}
          min={CUSTOM_CHROMA_RANGE.min}
          max={CUSTOM_CHROMA_RANGE.max}
          step={CUSTOM_CHROMA_RANGE.step}
          onValueChange={(chroma) => setCustomTheme({ chroma })}
          trackStyle={{
            background: `linear-gradient(to right, oklch(0.65 ${CUSTOM_CHROMA_RANGE.min} ${customTheme.hue}), oklch(0.65 ${CUSTOM_CHROMA_RANGE.max} ${customTheme.hue}))`,
          }}
        />
        {!isCustom && <p className="text-xs text-muted-foreground">Drag a slider to switch to the custom theme.</p>}
      </div>

      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <span className="text-xs font-medium">Radius</span>
          <span className="font-mono text-xs text-muted-foreground tabular-nums">{radius}rem</span>
        </div>
        <div role="radiogroup" aria-label="Border radius" className="grid grid-cols-5 gap-1 rounded-lg bg-muted p-1">
          {radiusOptions.map((r) => {
            const active = r.value === radius
            return (
              <button
                key={r.value}
                type="button"
                role="radio"
                aria-checked={active}
                aria-label={`${r.label} radius`}
                title={r.label}
                onClick={() => setRadius(r.value)}
                className={cn(
                  "flex items-center justify-center rounded-md py-1.5 transition-colors focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none",
                  active ? "bg-background shadow-sm" : "hover:bg-background/60"
                )}
              >
                <span
                  aria-hidden
                  className={cn("size-4 border-2 border-t-0 border-l-0", active ? "border-primary" : "border-muted-foreground/60")}
                  style={{ borderBottomRightRadius: `${Math.min(r.value, 0.9)}rem` }}
                />
              </button>
            )
          })}
        </div>
      </div>

      <CopyCssButton className="w-full" />
    </div>
  )
}

"use client"

import * as React from "react"
import { CheckIcon } from "lucide-react"
import { cn } from "@/lib/utils"
import type { ColorThemeId } from "@/lib/themes"

export interface ThemeSwatchProps extends Omit<React.ComponentProps<"button">, "onSelect"> {
  themeId: ColorThemeId
  label: string
  selected?: boolean
  size?: "sm" | "md" | "lg"
  onSelect?: (id: ColorThemeId) => void
}

const sizes = {
  sm: "size-6",
  md: "size-8",
  lg: "size-10",
}

/**
 * A circular preview of a color theme's primary color.
 *
 * It sets `data-theme` on itself, so the CSS rules in globals.css resolve
 * `--primary` for that theme on this element, in the current light/dark
 * mode, with no hard-coded hex values anywhere. The custom theme shows a
 * hue wheel ring around its current color instead.
 */
export function ThemeSwatch({ themeId, label, selected = false, size = "md", onSelect, className, ...props }: ThemeSwatchProps) {
  const isCustom = themeId === "custom"

  return (
    <button
      type="button"
      role="radio"
      aria-checked={selected}
      aria-label={label}
      title={label}
      data-theme={themeId}
      data-selected={selected ? "" : undefined}
      onClick={() => onSelect?.(themeId)}
      className={cn(
        "group relative inline-flex shrink-0 items-center justify-center rounded-full bg-primary text-primary-foreground",
        "ring-offset-background transition-transform duration-150 ease-out motion-reduce:transition-none",
        "hover:scale-110 focus-visible:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        "data-selected:ring-2 data-selected:ring-primary data-selected:ring-offset-2",
        isCustom && "bg-[conic-gradient(in_oklch_longer_hue,oklch(0.7_0.18_0),oklch(0.7_0.18_360))]",
        sizes[size],
        className
      )}
      {...props}
    >
      {isCustom && <span aria-hidden className="absolute inset-[3px] rounded-full bg-primary" />}
      <CheckIcon
        aria-hidden
        className={cn("relative size-1/2 transition-opacity", selected ? "opacity-100" : "opacity-0 group-hover:opacity-40")}
        strokeWidth={3}
      />
    </button>
  )
}

"use client"

import * as React from "react"
import { useTheme } from "next-themes"
import { MonitorIcon, MoonIcon, SunIcon } from "lucide-react"
import { modes, type Mode } from "@/lib/themes"
import { cn } from "@/lib/utils"
import { useMounted } from "@/hooks/use-mounted"
import { Button } from "@/components/ui/button"

const icons: Record<Mode, React.ComponentType<{ className?: string }>> = {
  light: SunIcon,
  dark: MoonIcon,
  system: MonitorIcon,
}

/** Segmented control: Light / Dark / System. */
export function ModeSegmentedControl({ className }: { className?: string }) {
  const { theme, setTheme } = useTheme()
  const mounted = useMounted()
  const current = (mounted ? theme : undefined) as Mode | undefined

  return (
    <div role="radiogroup" aria-label="Appearance" className={cn("grid grid-cols-3 gap-1 rounded-lg bg-muted p-1", className)}>
      {modes.map((m) => {
        const Icon = icons[m.id]
        const active = current === m.id
        return (
          <button
            key={m.id}
            type="button"
            role="radio"
            aria-checked={active}
            onClick={() => setTheme(m.id)}
            className={cn(
              "flex items-center justify-center gap-1.5 rounded-md px-2 py-1.5 text-xs font-medium transition-colors",
              "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              active ? "bg-background text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
            )}
          >
            <Icon className="size-3.5" />
            {m.label}
          </button>
        )
      })}
    </div>
  )
}

/** Compact sun / moon button that flips between light and dark. */
export function ModeToggle({ className }: { className?: string }) {
  const { resolvedTheme, setTheme } = useTheme()
  const mounted = useMounted()
  const isDark = mounted && resolvedTheme === "dark"

  return (
    <Button
      variant="outline"
      size="icon"
      aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
      onClick={() => setTheme(isDark ? "light" : "dark")}
      className={className}
    >
      <SunIcon className="size-4 scale-100 rotate-0 transition-all dark:scale-0 dark:-rotate-90" />
      <MoonIcon className="absolute size-4 scale-0 rotate-90 transition-all dark:scale-100 dark:rotate-0" />
    </Button>
  )
}

import { useSyncExternalStore } from "react"

const subscribe = () => () => {}

/**
 * `false` during SSR and hydration, `true` once the component is on the client.
 * Uses `useSyncExternalStore` so there is no extra render or state update.
 */
export function useMounted() {
  return useSyncExternalStore(
    subscribe,
    () => true,
    () => false
  )
}

/**
 * Color theme registry.
 *
 * This is the single source of truth for which color themes exist.
 * Each entry maps to a `[data-theme="<id>"]` rule in `globals.css` that sets
 * the theme's hue and chroma. Everything else (primary, ring, charts, accent)
 * is derived from those two numbers, so adding a theme is one line of CSS
 * plus one entry here.
 *
 * The "custom" entry is special: its hue and chroma come from the provider
 * (`--custom-hue` / `--custom-chroma` on <html>) instead of the stylesheet.
 */
export const colorThemes = [
  { id: "default", label: "Default", description: "Neutral zinc" },
  { id: "red", label: "Red", description: "Bold and energetic" },
  { id: "orange", label: "Orange", description: "Warm and friendly" },
  { id: "amber", label: "Amber", description: "Golden and bright" },
  { id: "lime", label: "Lime", description: "Fresh and zesty" },
  { id: "green", label: "Green", description: "Calm and natural" },
  { id: "teal", label: "Teal", description: "Cool and balanced" },
  { id: "sky", label: "Sky", description: "Light and airy" },
  { id: "blue", label: "Blue", description: "Trustworthy classic" },
  { id: "violet", label: "Violet", description: "Creative and rich" },
  { id: "fuchsia", label: "Fuchsia", description: "Vivid and playful" },
  { id: "pink", label: "Pink", description: "Soft and modern" },
  { id: "custom", label: "Custom", description: "Any hue you like" },
] as const

export type ColorTheme = (typeof colorThemes)[number]
export type ColorThemeId = ColorTheme["id"]

export const DEFAULT_COLOR_THEME: ColorThemeId = "default"
export const CUSTOM_COLOR_THEME: ColorThemeId = "custom"

/** The preset themes, i.e. everything except "custom". */
export const presetColorThemes = colorThemes.filter((t) => t.id !== CUSTOM_COLOR_THEME)

/** localStorage key the provider persists the selected color theme under.
 *  Custom hue/chroma and radius use `<key>-custom` and `<key>-radius`. */
export const COLOR_THEME_STORAGE_KEY = "color-theme"

/** The attribute on `<html>` that activates a color theme. */
export const COLOR_THEME_ATTRIBUTE = "data-theme"

export const colorThemeIds = colorThemes.map((t) => t.id) as ColorThemeId[]

export function isColorThemeId(value: unknown): value is ColorThemeId {
  return typeof value === "string" && (colorThemeIds as string[]).includes(value)
}

export function getColorTheme(id: ColorThemeId): ColorTheme {
  return colorThemes.find((t) => t.id === id) ?? colorThemes[0]
}

/* ------------------------------------------------------------------ */
/*  Custom theme                                                       */
/* ------------------------------------------------------------------ */

export interface CustomTheme {
  /** oklch hue, 0 to 360 */
  hue: number
  /** oklch chroma, roughly 0.05 to 0.3 */
  chroma: number
}

export const DEFAULT_CUSTOM_THEME: CustomTheme = { hue: 262, chroma: 0.2 }
export const CUSTOM_HUE_RANGE = { min: 0, max: 360, step: 1 } as const
export const CUSTOM_CHROMA_RANGE = { min: 0.04, max: 0.3, step: 0.005 } as const

export function clampCustomTheme(value: Partial<CustomTheme> | null | undefined): CustomTheme {
  const hue = Number(value?.hue)
  const chroma = Number(value?.chroma)
  return {
    hue: Number.isFinite(hue) ? Math.min(CUSTOM_HUE_RANGE.max, Math.max(CUSTOM_HUE_RANGE.min, hue)) : DEFAULT_CUSTOM_THEME.hue,
    chroma: Number.isFinite(chroma)
      ? Math.min(CUSTOM_CHROMA_RANGE.max, Math.max(CUSTOM_CHROMA_RANGE.min, chroma))
      : DEFAULT_CUSTOM_THEME.chroma,
  }
}

